-- AzerothRoute: talent plans from another source in place of the snapshot's (Builds.lua). The
-- snapshot keeps the class's tree (nodes, arrows, gates); the source brings its own plans and any
-- talents newer than the snapshot. Talents/IcyVeins.lua (generated by tools/fork/icyveins.lua)
-- calls it with Icy Veins' WoW Forever leveling builds. Original AzerothRoute code (GPL-3.0-only).
--
--   T.UseSource({ class, fixes = { [id] = { max, spell, name } },
--                 nodes = { [id] = { max, spell, spec, row, col, name } },
--                 builds = { { key, spec, split, link, updated, picks = { { node, rank } } } } })

local ADDON, ns = ...
local T = ns.Talents
local L = ns.L
if not T then return end

if GetLocale and (GetLocale() == "esMX" or GetLocale() == "esES") then
	L["Icy Veins' WoW Forever leveling guides"] = "las guías de subida de nivel de WoW Forever de Icy Veins"
	L["Picks from %s (%s, updated %s), one point a level, checked against the game's talent tree."] = "Talentos de %s (%s, actualizada el %s), un punto por nivel, comprobados con el árbol de talentos del juego."
end

function T.UseSource(def)
	local data = T.Data(def.class)
	-- Register keeps only the player's class.
	if not data or data.class ~= def.class then return end
	-- Snapshot talents the game has changed since: their ranks and name now.
	for id, f in pairs(def.fixes or {}) do
		local n = data.nodes[id]
		if n then n.max, n.spell, n.name = f[1], f[2], f[3] end
	end
	for id, n in pairs(def.nodes or {}) do
		data.nodes[id] = { id = id, max = n[1], spell = n[2], spec = n[3], row = n[4], col = n[5], name = n[6] }
	end
	local builds = {}
	for _, b in ipairs(def.builds) do
		local picks = {}
		for i, p in ipairs(b.picks) do picks[i] = { order = i, node = p[1], rank = p[2] } end
		builds[#builds + 1] = {
			key = b.key, spec = b.spec, split = b.split, link = b.link, updated = b.updated,
			picks = picks, notes = {}, data = data, specName = L[data.specs[b.spec]],
		}
	end
	data.builds = builds
	data.source = L["Icy Veins' WoW Forever leveling guides"]
	data.url = "https://www.icy-veins.com/wow-forever/leveling-guides"
	-- The snapshot's summary describes its own plans.
	data.summary = nil
end
